mapper.select:
SELECT COUNT(*)
  FROM docs_partner_company
 WHERE del_yn = 'N'
   AND business_no = #{businessNo}

   AND partner_company_id <> #{excludeCompanyId}

SELECT company.partner_company_id, company.company_code, company.company_name, partner_user.partner_user_id, partner_user.user_name, partner_user.email, partner_user.phone, partner_user.position_name, partner_user.representative_yn FROM docs_partner_company company JOIN docs_partner_user partner_user ON partner_user.partner_company_id = company.partner_company_id AND partner_user.use_yn = 'Y' AND partner_user.del_yn = 'N' WHERE company.use_yn = 'Y' AND company.del_yn = 'N'
AND company.partner_company_id = #{value}
ORDER BY company.company_name, partner_user.representative_yn DESC, partner_user.user_name, partner_user.partner_user_id
